async function startServer() {
  try {
    const distExists = fs2.existsSync(path2.join(process.cwd(), "dist", "index.html"));
    const isProduction = (process.env.NODE_ENV === "production" || Boolean(process.env.K_SERVICE) || Boolean(process.env.GAE_SERVICE) || process.env.npm_lifecycle_event === "start") && distExists;
    if (!isProduction) {
      const vite = await createViteServer({
        server: { middlewareMode: true },
        appType: "spa"
      });
      app.use(vite.middlewares);
    } else {
      const distPath = path2.join(process.cwd(), "dist");
      app.use(express.static(distPath));
      app.get("*", (_req, res) => {
        res.sendFile(path2.join(distPath, "index.html"));
      });
    }
    const server = app.listen(PORT, "0.0.0.0", () => {
      console.log(`[SERVER] Flawlesz AI app running on http://0.0.0.0:${PORT}`);
      console.log(`  \u279C  Local:   http://localhost:${PORT}/`);
      console.log(`  \u279C  Network: http://0.0.0.0:${PORT}/`);
    });
    server.on("error", (err) => {
      console.error(`[SERVER] Server error on port ${PORT}:`, err);
    });
    initDatabaseState().catch((err) => {
      console.error("[DB] Failed to initialize database state:", err);
    });
  } catch (err) {
    console.error("[SERVER] Fatal error during startServer:", err);
  }
}
